<?php $invoice=$receipt['invoice'];$currency=$invoice['currency_code']; ?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?= $h($invoice['name']) ?> · Comprobante</title>
<link rel="stylesheet" href="../../css/restaurant-receipt.css?v=<?= filemtime(dirname(__DIR__,2).'/css/restaurant-receipt.css') ?>"><script src="../../js/restaurant-receipt.js" defer></script></head><body>
<nav class="receipt-actions" aria-label="Acciones del comprobante"><a href="index.php">← Volver a las mesas</a><button type="button" data-receipt-print>Imprimir / Guardar PDF</button><a href="cuenta.php?id=<?= (int)$receipt['account']['id'] ?>">Ver cuenta</a></nav>
<main class="receipt"><header><p class="receipt-eyebrow">COMPROBANTE DE LA MESA</p><h1><?= $h($receipt['company']['legal_name']?:$receipt['company']['name']) ?></h1><p><?= $h($receipt['company']['tax_id']) ?></p><p><?= $h($receipt['company']['address']) ?></p><?php if($receipt['company']['phone']): ?><p><?= $h($receipt['company']['phone']) ?></p><?php endif; ?></header>
<section class="receipt-info"><div><span>Factura</span><strong><?= $h($invoice['name']) ?></strong><span><?= $h($invoice['invoice_date']) ?></span></div><div><span>Cuenta</span><strong><?= $h($receipt['account']['name']) ?></strong><span><?= $h($invoice['payment_state']==='paid'?'Pagada':'Estado: '.$invoice['payment_state']) ?></span></div></section>
<section><h2>Cliente</h2><p><?= $h($invoice['customer_name']) ?><?php if($invoice['customer_tax_id']): ?> · <?= $h($invoice['customer_tax_id']) ?><?php endif; ?></p><p><?= nl2br($h($invoice['invoice_address'])) ?></p></section>
<table><thead><tr><th>Producto</th><th>Cantidad</th><th>Precio</th><th>Total</th></tr></thead><tbody><?php foreach($receipt['lines'] as $line): ?><tr><td><?= $h($line['product_name']) ?></td><td><?= $h(bcadd($line['quantity'],'0',2)) ?></td><td><?= $h($line['unit_price']) ?></td><td><?= $h($line['total_amount']) ?></td></tr><?php endforeach; ?></tbody></table>
<dl class="receipt-totals"><div><dt>Subtotal</dt><dd><?= $h($invoice['base_amount'].' '.$currency) ?></dd></div><div><dt>Impuestos</dt><dd><?= $h($invoice['tax_amount'].' '.$currency) ?></dd></div><div class="receipt-total"><dt>Total</dt><dd><?= $h($invoice['total_amount'].' '.$currency) ?></dd></div></dl>
<section><h2>Pagos confirmados</h2><?php foreach($receipt['payments'] as $payment): ?><div class="receipt-payment"><div><strong><?= $h($payment['method_name']) ?></strong><span><?= $h($payment['reference']) ?></span></div><strong><?= $h($payment['amount'].' '.$payment['currency_code']) ?></strong><?php if(bccomp($payment['change_amount'],'0',2)>0): ?><small>Recibido: <?= $h($payment['received_amount'].' '.$payment['currency_code']) ?> · Cambio: <?= $h($payment['change_amount'].' '.$payment['currency_code']) ?></small><?php endif; ?></div><?php endforeach; ?><?php if(!$receipt['payments']): ?><p>No hay cobros confirmados vigentes.</p><?php endif; ?></section>
<?php if(($receipt['audit']['split_mode']??'full')!=='full'): ?><section><h2>Reparto de la cuenta</h2><?php foreach($receipt['audit']['payments']??[] as $index=>$part): ?><div class="receipt-share"><p><?= $h($part['label']?:'Persona '.($index+1)) ?>: <strong><?= $h($part['amount'].' '.$currency) ?></strong></p><?php if($part['items']): ?><ul><?php foreach($part['items'] as $itemId=>$quantity): ?><li><?= $h($quantity.' × '.($receipt['itemsById'][$itemId]??'Producto')) ?></li><?php endforeach; ?></ul><?php endif; ?></div><?php endforeach; ?></section><?php endif; ?>
<footer>Comprobante de la factura <?= $h($invoice['name']) ?> registrada en el sistema. Para guardar un PDF, selecciona «Guardar como PDF» en la ventana de impresión.</footer>
</main></body></html>
